"""SCMOVS update: elections now OPEN automatically at their scheduled start time (as well as closing at the end time).

How it behaves
  * A SCHEDULED election opens by itself when its start time arrives, using the same checks as the "Open voting" button
    (positions, an approved candidate for every position, no pending candidates, active school year, no overlapping
    election). Drafts are never opened.
  * If a check fails, the Super Admins and School Admins get ONE notice with the reason, and the system keeps retrying:
    fix the problem (for example approve the pending candidate) and the election opens by itself.
  * It closes by itself at the end time (as before). Checks run about every 15 seconds.

NO database change is needed for this update.

HOW TO USE
  1. Put this file in your project folder (the folder that contains run.py).
  2. In PowerShell, inside that folder, run:   python apply_autostart_update.py
  3. Restart the app (python run.py).

Your current copy of every file it replaces is saved first in _update_backup/ (same sub-folders).
"""
import base64
import os
import shutil
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
FILES = {
    'app/elections/auto_close.py': "",
    'app/elections/services.py': "",
    'close_due_elections.py': "",
    'templates/elections/detail.html': "",
    'tests/run_all.sh': "",
    'tests/test_auto_open.py': "",
}


def main():
    if not os.path.isfile(os.path.join(ROOT, "run.py")) or not os.path.isdir(os.path.join(ROOT, "app")):
        print("STOP: put this file in your project folder (the one that has run.py and the app folder), then run it again.")
        sys.exit(1)
    if not os.path.isfile(os.path.join(ROOT, "app", "elections", "auto_close.py")):
        print("STOP: this update builds on the previous one (apply_big_update.py). Apply that one first.")
        sys.exit(1)
    for rel, encoded in FILES.items():
        target = os.path.join(ROOT, *rel.split("/"))
        if os.path.isfile(target):
            saved = os.path.join(ROOT, "_update_backup", *rel.split("/"))
            os.makedirs(os.path.dirname(saved), exist_ok=True)
            if not os.path.exists(saved):
                shutil.copy2(target, saved)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "wb") as handle:
            handle.write(base64.b64decode(encoded))
        print("  updated", rel)
    print("\nDone. Restart the app (python run.py).")


if __name__ == "__main__":
    main()
